            where = self._parse_expr()

        # GROUP BY
        group_by = []
        if self.peek().kind == "KEYWORD" and self.peek().value == "group":
            self.advance()
            self.expect("KEYWORD", "by")
            group_by = self._parse_expr_list()

        # HAVING
        having = None
        if self.peek().kind == "KEYWORD" and self.peek().value == "having":
            self.advance()
            having = self._parse_expr()

        # ORDER BY
        order_by = []
        if self.peek().kind == "KEYWORD" and self.peek().value == "order":
            self.advance()
            self.expect("KEYWORD", "by")
            order_by = self._parse_order_by()

        # LIMIT
        limit = None
        if self.peek().kind == "KEYWORD" and self.peek().value == "limit":
            self.advance()
            limit = self._parse_int()

        # OFFSET
        offset = None
        if self.peek().kind == "KEYWORD" and self.peek(). value == "offset":
            self.advance()
            offset = self._parse_int()

        return Query(distinct, select, from_table, join, where, group_by, having, order_by, limit, offset)

    def _parse_select_items(self) -> list[SelectItem]:
        items = []
 while self.peek().kind != "KEYWORD" or self.peek().value not in ("from", "where", "group", "having", "order", "limit", "offset"):
            if self.peek().kind == "OP" and self.peek().value == "*":
                self.advance()
                items.append( SelectItem(None, None, "*"))
            elif self.peek().kind == "IDENT":
                table = None
                name = self.advance().value
                if self.peek().kind == "OP" and self.peek().value == ".":
                    self.advance()
                    if self.peek().kind == "OP" and self.peek().value == "*":
                        self.advance()
                        items.append(SelectItem(None, None, f"{name}.*"))
                    else:
                        col_name = self.advance().value
                        items.append(SelectItem(None, None, f"{name}.{col_name}"))
                else:
                    items.append( SelectItem(None, None, name))
            else:
                expr = self._parse_expr()
                alias = None
                if self.peek().kind == "KEYWORD" and self.peek().value == "as":
                    self.advance()
                    alias = self.advance().value
                items.append(SelectItem(expr, alias, expr.source))
            if self.peek().kind == "OP" and self.peek().value == ",":
                self.advance()
        return items

    def _parse_table_name(self) -> str:
        t = self.expect("IDENT")
        return t.value

    def _parse_expr(self) -> Expr :
        return self._parse_or_expr()

    def _parse_or_expr(self) -> Expr:
        expr = self._parse_and_expr()
        while self.peek().kind == "KEYWORD" and self.peek().value == "or":
            self.advance()
            right = self._parse_and_expr()
            expr = BinaryOp("OR", expr, right, "")
        return expr

    def _parse_and_expr(self) -> Expr:
        expr = self._parse_not_expr()
        while self.peek().kind == "KEYWORD" and self.peek().value == "and":
            self.advance()
            right = self ._parse_not_expr()
            expr = BinaryOp("AND", expr, right, "")
        return expr

    def _parse_not_expr(self) -> Expr:
        if self.peek().kind == "KEYWORD" and self.peek().value == "not":
            self.advance()
            expr = self._parse_not expr()
            return UnaryOp("NOT", expr, "")
        return self._parse_predicate()

    def _parse_predicate(self) -> Expr:
        left = self._parse_additive()
        if self.peek().kind == "OP" and self.peek().value in ("=", "<>", "<", "< =", ">", ">="):
            op = self.advance().value
            right = self._parse_additive()
            return BinaryOp(op, left, right, "")
        elif self.peek().kind == "KEYWORD" and self.peek().value == "is":
            self.advance()
            if self.peek().kind == "KEYWORD" and self.peek().value == "not":
                self.advance()
                self.expect("KEYWORD", "null")
                return IsNull(left, True, "")
            else:
                self.expect("KEYWORD", "null")
                return IsNull(left, False, "")
        return left

    def _parse_additive(self) -> Expr:
        expr = self._parse_multiplicative()
        while self.peek().kind == "OP" and self.peek().value in ("+", "-"):
            op = self.advance().value
            right = self._parse_multiplicative()
            expr = BinaryOp(op, expr , right, "")
        return expr

    def _parse_multiplicative(self) -> Expr:
        expr = self._parse_unary()
        while self.peek().kind == "OP" and self.peek().value in ("*", "/", "%"):
            op = self.advance().value
            right = self._parse_un ary()
            expr = BinaryOp(op, expr, right, "")
        return expr

    def _parse_unary(self) -> Expr:
        if self.peek().kind == "OP" and self.peek().value == "-":
            self.advance()
            expr = self._parse_unary()
            return UnaryOp ("-", expr, "")
        return self._parse_primary()

    def _parse_primary(self) -> Expr:
        t = self.peek()
        if t.kind == "INT":
            self.advance()
            return Literal(int(t.value), t.value)
        elif t.kind == "FLOAT":
            self.advance()
            return Literal(float(t.value), t.value)
        elif t.kind == "TEXT":
            self.advance()
            return Literal(t.value, t.value)
        elif t.kind == "KEYWORD" and t.value == "true":
            self.advance()
            return Literal(True, "true")
        elif t.kind == " KEYWORD" and t.value == "false":
            self.advance()
            return Literal(False, "false")
        elif t.kind == "KEYWORD" and t.value == "null":
            self.advance()
            return Literal(None, "null")
        elif t.kind == "IDENT":
            self.advance()
            name = t.value
            if self.peek().kind == "OP" and self.peek().value == ".":
                self.advance()
                if self.peek().kind == "OP" and self.peek().value == "*":
                    self.advance()
                    return ColumnRef(None, f"{name}.*", "")
                else:
                    col_name = self.advance().value
                     return ColumnRef(name, col_name, "")
            elif self.peek().kind == "OP" and self.peek().value == "(":
                self.advance()
                args = []
                if self.peek().kind != "OP" or self.peek().value != ")":
                    args = self._parse_arg_list()
                self.expect("OP", ")")
                return FuncCall(name, args, False, "")
            else:
                return ColumnRef(None, name, "")
        elif t.kind == "OP" and t.value == "(":
            self.advance()
            expr = self._parse_expr()
 self.expect("OP", ")")
            return expr
        else:
            raise ParseError(t.offset)

    def _parse_arg_list(self) -> list[Expr]:
        args = []
        while True:
            args.append(self._parse_expr())
            if self.peek().kind == "OP" and self.peek .value == ",":
                self.advance()
            else:
                break
        return args

    def _parse_expr_list(self) -> list[Expr]:
        exprs = []
        while True:
            exprs.append(self._parse_expr())
            if self.peek().kind == "OP" and self.peek(). value == ",":
                self.advance()
            else:
                break
        return exprs

    def _parse_order_by(self) -> list[OrderItem]:
        items = []
        while True:
            expr = self._parse_expr()
            desc = False
            if self.peek().kind == "KEYWORD and self.peek().value == "asc":
                self.advance()
            elif self.peek().kind == "KEYWORD" and self.peek().value == "desc":
                self.advance()
                desc = True
            items.append(OrderItem(expr, desc))
            if self.peek().kind == "OP" and self.peek .value == ",":
                self.advance()
            else:
                break
        return items

    def _parse_int(self) -> int:
        t = self.expect("INT")
        return int(t.value)
