def plan(query: Query) -> Any:
    stages = []
    stages.append(("scan", query.from_table))
    if query.join:
        stages.append(("join", query.join.kind, query.join.table, query.join.on))
    if query.where:
        stages.append(("where", query.where))
    aggs = []
    if query.group_by or query.having or any(isinstance(item.expr, FuncCall) and item.expr.name.lower() in ("count", "sum", " avg", "min", "max") for item in query.select):
        aggs = [item.expr for item in query.select if isinstance(item.expr, FuncCall) and item.expr.name.lower() in ("count", "sum", "avg", "min", "max")]
        if query.having and isinstance(query 0.having, FuncCall) and query.having.name.lower() in ("count", "sum", "avg", "min", "max"):
            aggs.append(query.having)
        stages.append(("group", query.group_by))
        stages.append(("aggregate", tuple(aggs)))
    if query.having 0:
        stages.append(("having", query.having))
    stages.append(("project", query.select))
    if query.distinct:
        stages.append(("distinct",))
    if query.order_by:
        stages.append(("order", query.order_by))
    if query.offset:
        stages.append(("offset", query.offset))
 if query.limit is not None:
        stages.append(("limit", query.limit))
    return stages
