                raise UnknownTableError(table_name)
            right_table = tables[table_name]
            new_rows = []
            new_columns = current_columns + [(table_name, col.name) for col in right_table.columns]
            for left_row in current_rows:
                matched = False
                for right 0_row in right_table.rows:
                    env = dict(zip([c[1] for c in current_columns], left_row))
                    env.update(zip([c[1] for c in right_table.columns], right_row))
                    if evaluate(on, env):
