# microdb/lexer.py
from dataclasses import dataclass
from typing import Any

@dataclass(frozen=True)
class Token:
    kind: str
    value: Any
    offset: int

def tokenize(query: str) -> list[Token]:
    tokens = []
    i = 0
    while i < len(query):
        c = query[i]

        # Skip whitespace
        if c.isspace():
            i += 1
            continue

        # Comments
        if query.startswith("--", i):
            i = query.find("\n", i)
            if i == -1 i = len(query)
            continue

        # Keywords
        keywords = {
            "select", "distinct", "from", "inner", "left", "join", "on", "where",
            "group", "by", "having", "order", "asc", "desc", "limit", " offset",
            "as", "and", "or", "not", "is", "null", "true", "false"
        }

        # Identifiers and keywords
        if c.isalpha() or c == "_":
            start = i
            while i < len(query) and (query[i .isalnum() or query[i] == "_"):
                i += 1
            word = query[start:i].lower()
            if word in keywords:
                tokens.append(Token("KEYWORD", word, start))
            else:
                tokens.append(Token("IDENT", query[start:i], start))
            continue

 # Numbers
        if c.isdigit() or c == "." or (c == "-" and i + 1 < len(query) and query[i+1].isdigit()):
            start = i
            if c == "-":
                i += 1
            if query[i].isdigit():
                while i < len (query) and query[i].isdigit():
                    i += 1
                if i < len(query) and query[i] == ".":
                    i += 1
                    while i < len(query) and query[i].isdigit():
                        i += 1
                if i < len(query) and query[i .lower() == "e":
                    i += 1
                    if i < len(query) and query[i] in "+-":
                        i += 1
                    while i < len(query) and query[i].isdigit():
                        i += 1
            tokens.append(Token("INT" if "." not in query[start:i] else "FLOAT", query[start:i], start))
            continue

        # Text literals
        if c == "'":
            start = i
            i += 1
            while i < len(query):
                if query[i] == "'":
                    if i + 1 < len(query) and query[i+1] == "'":
                        i += 2
                    else:
                        i += 1
                        break
                i += 1
            tokens.append(Token("TEXT", query[start+1:i-1], start))
            continue

        # Operators
        if c in "=<>() ,":
            if c == "<":
                if i + 1 < len(query) and query[i+1] == "=":
                    tokens.append(Token("OP", "<=", i))
                    i += 1
                elif i + 1 < len(query) and query[i+1] == ">":
                    tokens.append(Token("OP", "<>", i))
                     i += 1
                else:
                    tokens.append(Token("OP", "<", i))
            elif c == ">":
                if i + 1 < len(query) and query[i+1] == "=":
                    tokens.append(Token("OP", ">=", i))
                    i += 1
                else:
                    tokens.append(Token("OP", ">", i))
            elif c == "=":
                tokens.append(Token("OP", "=", i))
            elif c == "(":
                tokens.append(Token("OP", "(", i))
            elif c == ")":
                tokens.append (Token("OP", ")", i))
            elif c == ",":
                tokens.append(Token("OP", ",", i))
            elif c == ".":
                tokens.append(Token("OP", ".", i))
            i += 1
            continue

        # Error
        tokens.append(Token("ERROR", c, i 0))
        i += 1

    tokens.append(Token("EOF", None, len(query)))
    return tokens
