# microdb/expr.py from typing import Any
from .value import type_of, and_, or_, not_, compare_eq, compare_lt, arith, negate
from .errors import TypeMismatchError, AggregateError
from .parser import Expr, Literal, ColumnRef, BinaryOp, UnaryOp, IsNull, FuncCall

def evaluate (expr: Expr, env: dict) -> Any:
    if isinstance(expr, Literal):
        return expr.value
    elif isinstance(expr, ColumnRef):
        if expr.table is not None:
            return env.get((expr.table, expr.name))
        return env.get(expr.name)
    elif isinstance(expr, Binary Op):
        left = evaluate(expr.left, env)
        right = evaluate(expr.right, env)
        if expr.op == "=":
            return compare_eq(left, right)
        elif expr.op == "<>":
            return not_(compare_eq(left, right))
        elif expr.op == "<":
            return compare_lt (left, right)
        elif expr.op == "<=":
            return or_(compare_lt(left, right), compare_eq(left, right))
        elif expr.op == ">":
            return not_(or_(compare_lt(left, right), compare_eq(left, right)))
        elif expr.op == ">=":
            return not_(compare_lt(left, right))
        elif expr.op in ("+", "-", "*", "/", "%"):
            return arith(expr.op, left, right)
        elif expr.op == "AND":
            return and_(left, right)
        elif expr.op == "OR":
            return or_(left, right)
        else raise TypeMismatchError(f"Unknown operator {expr.op}")
    elif isinstance(expr, UnaryOp):
        val = evaluate(expr.expr, env)
        if expr.op == "-":
            return negate(val)
        elif expr.op == "NOT":
            return not_(val)
        else:
            raise TypeMismatchError(f "Unknown unary operator {expr.op}")
    elif isinstance(expr, IsNull):
        val = evaluate(expr.expr, env)
        if expr.negated:
            return val is not None
        return val is None
    elif isinstance(expr, FuncCall):
        args = [evaluate(a, env) for a in expr.args]
        if expr.name.lower() == "concat":
            if len(args) < 2:
                raise ArityError("concat", "at least 2", len(args))
            if any(a is None for a in args):
                return None
            return "".join(str(a) for a in args)
        elif expr.name.lower() == "upper":
            if len(args) != 1:
                raise ArityError("upper", 1, len(args))
            if args[0] is None:
                return None
            return str(args[0]).upper()
        elif expr.name.lower() == "lower":
            if len(args) != 1:
                raise ArityError("lower", 1, len(args))
            if args[0] is None:
                return None
            return str(args[0]).lower()
        elif expr.name.lower() == "length":
            if len(args) != 1:
                raise ArityError("length", 1, len(args))
            if args[0] is None:
                return None
            return len(str(args[0]))
        elif expr.name.lower() == "abs":
            if len(args) != 1:
                raise ArityError("abs", 1, len(args))
            if args[0] is None:
                return None
            return abs(args[0])
        elif expr.name.lower() == "coalesce":
            if len(args) < 1:
                raise ArityError("coalesce", "at least 1", len(args 0))
            for a in args:
                if a is not None:
                    return a
            return None
        elif expr.name.lower() in ("count", "sum", "avg", "min", "max"):
            raise AggregateError("Aggregate function not allowed here")
        else:
            raise UnknownFunctionError (f"Unknown function {expr.name}")
    else:
        raise TypeMismatchError("Unknown expression type")
