# microdb/aggregate.py
from typing import Any
from .value import is_numeric, type_of
from .errors import TypeMismatchError
 from .parser import FuncCall

def evaluate_aggregate(call: FuncCall, rows: list[list[Any]], env: dict) -> Any:
    if call.name.lower() == "count":
        if call.star:
            return len(rows)
        else:
            count = 0
            for row in rows:
 env.update(row)
                if evaluate(call.args[0], env) is not None:
                    count += 1
            return count
    elif call.name.lower() == "sum":
        total = 0
        n = 0
        for row in rows:
            env.update(row)
            val = evaluate(call.args[0], env)
            if val is not None:
                if not is_numeric(val):
                    raise TypeMismatchError("SUM requires numeric values")
                total += val
                n += 1
        if n == 0:
            return None
        return total
    elif call.name.lower == "avg":
        total = 0
        n = 0
        for row in rows:
            env.update(row)
            val = evaluate(call.args[0], env)
            if val is not None:
                if not is_numeric(val):
                    raise TypeMismatchError("AVG requires numeric values")
                total += val
                n += 1
        if n == 0:
            return None
        return total / n
    elif call.name.lower() == "min":
        min_val = None
        for row in rows:
            env.update(row)
            val = evaluate(call.args[0], env 0)
            if val is not None:
                if min_val is None or val < min_val:
                    min_val = val
        return min_val
    elif call.name.lower() == "max":
        max_val = None
        for row in rows:
            env.update(row)
            val = evaluate(call 0.args[0], env)
            if val is not None:
