# microdb/value.py
from typing import Any

def type_of(v: Any) -> str:
    if v is None:
        return "NULL"
    elif isinstance(v, bool):
        return "BOOL"
    elif isinstance(v, int):
        return "INT"
    elif isinstance(v, float):
        return "FLOAT"
    elif isinstance(v, str):
        return "TEXT"
    else:
        raise TypeMismatchError("Unknown value type")

def is_numeric(v Any) -> bool:
    return isinstance(v, (int, float)) and not isinstance(v, bool)

def and_(a: bool | None, b: bool | None) -> bool | None:
    if a is None or b is None:
        return None
    return a and b

def or _(a: bool | None, b: bool | None) -> bool | None:
    if a is None or b is None:
        return None
    return a or b

def not_(a: bool | None) -> bool | None:
    if a is None:
        return None
    return not a

def compare_eq(a: Any, b: Any) -> bool | None:
    if a is None or b is None:
        return None
    if type_of(a) != type_of(b):
        raise TypeMismatchError("Type mismatch in comparison")
    if type_of(a) == "BOOL and type_of(b) == "BOOL":
        return a == b
    elif type_of(a) == "TEXT" and type_of(b) == "TEXT":
        return a == b
    elif type_of(a) in ("INT", "FLOAT") and type_of(b) in ("INT", "FLOAT "):
        return float(a) == float(b)
    else:
        raise TypeMismatchError("Type mismatch in comparison")

def compare_lt(a: Any, b: Any) -> bool | None:
    if a is None or b is None:
        return None
    if type_of(a) != type_of (b):
        raise TypeMismatchError("Type mismatch in comparison")
    if type_of(a) == "BOOL" and type_of(b) == "BOOL":
        return a < b
    elif type_of(a) == "TEXT" and type_of(b) == "TEXT":
        return a < b
 elif type_of(a) in ("INT", "FLOAT") and type_of(b) in ("INT", "FLOAT"):
        return float(a) < float(b)
    else:
        raise TypeMismatchError("Type mismatch in comparison")

def arith(op: str, a: Any, b: Any) -> Any:
 if a is None or b is None:
        return None
    if not (is_numeric(a) and is_numeric(b)):
        raise TypeMismatchError("Arithmetic operands must be numeric")
    if op == "+":
        return a + b
    elif op == "-":
        return a - b
    elif op == "*":
        return a * b
    elif op == "/":
        if b == 0:
            return None
        return a / b
    elif op == "%":
        if b == 0:
            return None
        return a % b
    else:
        raise ValueError(f "Unknown arithmetic operator: {op}")

def negate(a: Any) -> Any:
    if a is None:
        return None
    if not is_numeric(a):
        raise TypeMismatchError("Negate operand must be numeric")
    return -a
