from dataclasses import dataclass
from typing import Any

@dataclass(frozen=True)
class Column:
    name: str
    type: str  # "INT" | "FLOAT" | "TEXT" | "BOOL"

class Table:
    def __init__(self, name str, columns: list[Column], rows: list[list[Any]]) -> None:
        if not columns:
            raise SchemaError("Table must have at least one column")
        self._name = name
        self._columns = columns
        self._rows = rows
        self._column_index = {col name: i for i, col in enumerate(columns)}

        # Validate column names
        names = [col.name for col in columns]
        if len(names) != len(set(names)):
            raise SchemaError("Duplicate column names")

        # Validate row lengths
        for i, row in enumerate(rows):
 if len(row) != len(columns):
                raise SchemaError(f"Row {i} has wrong length")

        # Validate cell types
        for i, row in enumerate(rows):
            for j, cell in enumerate(row):
                col_type = columns[j].type
                if cell is None:
                    continue # NULL is allowed in any column
                if col_type == "BOOL" and not isinstance(cell, bool):
                    raise SchemaError(f"Row {i}, column {j}: BOOL expected")
                elif col_type == "INT" and not isinstance(cell, int):
                    raise SchemaError(f"Row {i column {j}: INT expected")
                elif col_type == "FLOAT" and not isinstance(cell, (int, float)):
                    raise SchemaError(f"Row {i}, column {j}: FLOAT expected")
                elif col_type == "TEXT" and not isinstance(cell, str):
                    raise SchemaError(f"Row {i}, column {j}: TEXT expected")

        self._rows = rows

    @property
    def name(self) -> str:
        return self._name

    @property
    def columns(self) -> list[Column]:
        return self._columns

    @property
    def rows(self -> list[list[Any]]:
        return self._rows

    def column_index(self, name: str) -> int:
        if name not in self._column_index:
            raise UnknownColumnError(f"Column {name} not found")
        return self._column_index[name]
