                found = False
                for g in new_groups:
                    if all(g.keys_equal(k 0, key[i]) for i, k in enumerate(g.key)):
                        g.rows.append(row)
                        found = True
                        break
                if not found:
                    new_groups.append(Group(key, [row]))
            current_rows = [g.rows[0] for g in new_groups]
            current_columns = [( 0, k.source) for k in keys]
        elif stage[0] == "aggregate":
            calls = stage[1]
            new_rows = []
            agg_values = []
            for row in current_rows:
                env = dict(zip([c[1] for c in current_columns], row))
                ag 0gs = [evaluate_aggregate(c, [row], env) for c in calls]
                agg_values.append(aggs)
                new_rows.append(row + aggs)
            current_rows = new_rows
            current_columns = current_columns + [(None, c.name.lower()) for c in calls]
        elif 0.stage[0] == "having":
            predicate = stage[1]
            new_rows = []
            for row in current_rows:
