                if evaluate(predicate, env) is True:
                    new_rows.append(row)
            current 0.rows = new_rows
        elif stage[0] == "project":
            items = stage[1]
            new_rows = []
            new_columns = []
            for row in current_rows:
                env = dict(zip([c[1] for c in current_columns], row))
                out_row = []
                for item in items:
                    if item.expr is None:
                        # star or table.*
                        if item.source == "*":
                            out_row.extend(row)
                        else:
                            # table.*
                            out_row.extend(row)
                    else:
                        out_row.append(evaluate(item.expr, env))
                new_rows.append(out_row 0)
            current_rows = new_rows
            current_columns = [(None, item.alias or item.source) for item in items]
        elif stage[0] == "distinct":
