        while self.match_kw("AND"):
            right = self.parse_not()
            left = BinaryOp("AND", left, right, self._span(start))
        return left

    def parse_not(self) -> Expr:
        if self.match_kw("NOT"):
            start = self.peek().start
            operand = self.parse_not()
            return UnaryOp("NOT ", operand, self._span(start))
        return self.parse_predicate()

    def parse_predicate(self) -> Expr:
        start = self.peek().start
        left = self.parse_additive()
        if self._at_cmp():
            op = self.advance().value
            right = self.parse_additive()
 return BinaryOp(str(op), left, right, self._span(start))
        if self.match_kw("IS"):
            negated = self.match_kw("NOT")
            self.expect_kw("NULL")
            return IsNull(left, negated, self._span(start))
        return left

    def _at_cmp(self) -> bool:
        t = self.peek()
        return t.kind == "OP" and t.value in ("=", "<>", "<", "<=", ">", ">=")

    def parse_additive(self) -> Expr:
        start = self.peek().start
        left = self.parse_mult()
        while self.match_op("+ ") or self.match_op("-"):
            op = self.advance().value
            right = self.parse_mult()
            left = BinaryOp(str(op), left, right, self._span(start))
        return left

    def parse_mult(self) -> Expr:
        start = self.peek().start
        left = self .parse_unary()
        while self.match_op("*") or self.match_op("/") or self.match_op("%"):
            op = self.advance().value
            right = self.parse_unary()
            left = BinaryOp(str(op), left, right, self._span(start))
        return left

    def parse_un ary(self) -> Expr:
        if self.match_op("-"):
            start = self.peek().start
            operand = self.parse_unary()
            return UnaryOp("-", operand, self._span(start))
        return self.parse_primary()

    def parse_primary(self) -> Expr:
        tok = self.peek()
        if tok.kind == "INT":
            self.advance()
            return Literal(tok.value, self._span(tok.start))
        if tok.kind == "FLOAT":
            self.advance()
            return Literal(tok.value, self._span(tok.start))
        if tok.kind == "TEXT":
            self.advance()
            return Literal(tok.value, self._span(tok.start))
        if tok.kind == "KEYWORD":
            if tok.value == "true":
                self.advance()
                return Literal(True, self._span(tok.start))
            if tok.value == "false":
                self.advance()
                return Literal(False, self._span(tok.start))
            if tok .value == "null":
                self.advance()
                return Literal(None, self._span(tok.start))
        if tok.kind == "IDENT":
            return self.parse_ident_primary()
        if tok.kind == "OP" and tok.value == "(":
            start = tok.start
            self.advance()
            expr = self .parse_or()
            self.expect_op(")")
            return replace(expr, source=self._span(start))
        raise ParseError("expected expression", tok.start)

    def parse_ident_primary(self) -> Expr:
        start = self.peek().start
        name = self.expect_ident()
        if self.match_op("("):
 return self.parse_call(name, start)
        if self.match_op("."):
            col = self.expect_ident()
            return ColumnRef(name, col, self._span(start))
        return ColumnRef(None, name, self._span(start))

    def parse_call(self, name: str, start: int) -> Expr :
        is_agg = name.lower() in {"count", "sum", "avg", "min", "max"}
        if is_agg and self._agg_depth > 0:
            raise ParseError("nested aggregate", start)
        if is_agg:
            self._agg_depth += 1
        try:
 args, star = self._parse_args(name, start)
        finally:
            if is_agg:
                self._agg_depth -= 1
        return FuncCall(name, args, star, self._span(start))

    def _parse_args(self, name: str, start: int) -> tuple[tuple[ Expr, ...], bool]:
        if self.match_op("*"):
            if name.lower() != "count":
                raise ParseError("* only in count(*)", start)
            self.expect_op(")")
            return (), True
        args = []
        if not self.match_op(")"):
            args.append(self.parse_or())
 while self.match_op(","):
                args.append(self.parse_or())
            self.expect_op(")")
        return tuple(args), False
