# microdb/schema.py
import dataclasses
from typing import Any

@dataclasses.dataclass(frozen=True)
class Column:
    name: str
    type: str

class Table:
 def __init__(self, name: str, columns: list[Column], rows: list[list[object]]):
        if not columns:
            raise SchemaError("empty columns")
        seen = set()
        for c in columns:
            if c.name in seen:
                raise SchemaError("duplicate column")
            seen.add(c.name)
            if c.type not in ("INT", "FLOAT", "TEXT", "BOOL"):
                raise SchemaError("invalid type")
        self._name = name
        self._columns = columns
        self._rows = []
        for r in rows:
            if len(r) != len (columns):
                raise SchemaError("row length mismatch")
            new_r = []
            for i, v in enumerate(r):
                col = columns[i]
                if v is None:
                    new_r.append(None)
                    continue
                if col.type == "BOOL":
                    if not isinstance(v, bool):
                        raise SchemaError("bool cell mismatch")
                    new_r.append(v)
                elif col.type == "INT":
                    if isinstance(v, float):
                        raise SchemaError("float in int column")
                    if not isinstance(v, int):
                        raise SchemaError("int cell mismatch")
                    new_r.append(v)
                elif col.type == "FLOAT":
                    if isinstance(v, int):
                        new_r.append(float(v))
                    elif isinstance(v, float):
                        new_r.append(v)
                    else:
                        raise SchemaError("float cell mismatch")
                else:  # TEXT
                    if not isinstance(v, str):
                        raise SchemaError ("text cell mismatch")
                    new_r.append(v)
            self._rows.append(new_r)
    @property
    def name(self) -> str:
        return self._name
    @property
    def columns(self) -> list[Column]:
        return self._columns
    @property
    def rows (self) -> list[list[object]]:
        return self._rows
    def column_index(self, name: str) -> int:
        for i, c in enumerate(self.columns):
            if c.name == name:
                return i
        raise SchemaError(f"unknown column {name}")
