# microdb/value.py
from typing import Any

def type_of(v: object) -> str:
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "BOOL"
    if isinstance(v, int):
        return " INT"
    if isinstance(v, float):
        return "FLOAT"
    if isinstance(v, str):
        return "TEXT"
    raise TypeMismatchError("unknown value kind")

def is_numeric(v: object) -> bool:
    return isinstance(v, (int, float)) and not isinstance(v, bool)

def and_(a: bool | None, b: bool | None) -> bool | None:
    if a is None or b is None:
        return None
    return a and b

def or_(a: bool | None, b: bool | None) -> bool | None:
    if a is None or b is None:
        return None
    return a or b

def not_(a: bool | None) -> bool | None:
    if a is None:
        return None
    return not a

def compare_eq(a: object, b: object) -> bool | None:
    if a is None or b is None:
        return None
    if type_of(a) != type_of(b):
        raise TypeMismatchError("type mismatch")
    if a == b:
        return True
    return False

def compare_lt(a: object, b: object) -> bool | None:
    if a is None or b is None:
        return None
    ta = type_of(a)
    tb = type_of(b)
    if ta != tb:
        raise TypeMismatchError("type mismatch")
    if ta == "BOOL":
        return (not a) and b
    if ta == "TEXT":
        return a < b
    if ta in ("INT", "FLOAT"):
        return a < b
    raise TypeMismatchError("type mismatch")

def arith(op: str, a: object, b: object) -> object:
    if a is None or b is None:
        return None
    if not ( is_numeric(a) and is_numeric(b)):
        raise TypeMismatchError("type mismatch")
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "/":
        if b == 0:
            return None
        return a / b
    if op == "%":
        if b == 0:
            return None
        return a % b
    raise TypeMismatchError("unknown op")

def negate(a: object) -> object:
    if a is None:
        return None
    if not is_numeric(a):
        raise TypeMismatchError("type mismatch")
    return -a
