from dataclasses import dataclass
from typing import Any

@dataclass
class Token:
    kind: str
    value: Any
    start: int
    end: int

class Lexer:
    def __init__(self, src: str):
        self.src = src # keep original for source spans
        self.tokens: list[Token] = []
        self.i = 0
        self._lex()

    def _lex(self):
        text = self.src
        n = len(text)
        while self.i < n:
            ch = text[self.i]
            if ch == " " or ch == "\t" or ch == "\n":
                self.i += 1
                continue
            if ch == "-":
                if self.i + 1 < n and text[self.i + 1] == "-":
                    self.i += 2
                    while self.i < n and text[self.i] != "\n":
                        self.i += 1
                    continue
                self.i += 1
                self.tokens.append(Token("OP", "-", self.i - 1, self.i))
                continue
            if ch.isdigit() or (ch == "." and self.i + 1 < n and text[self.i + 1].isdigit()):
                self.tokens.append(self._read_number())
                continue
            if ch == ".":
                self.i += 1
                self.tokens.append(Token("OP", ".", self.i - 1, self.i))
                continue
            if ch == "'":
 self.i += 1
                start = self.i
                while self.i < n and text[self.i] != "'":
                    self.i += 1
                if self.i == n:
                    raise LexError("unterminated string", start)
                val = text[start:self.i].replace("''", "' ")
                self.i += 1
                self.tokens.append(Token("TEXT", val, start - 1, self.i))
                continue
            if ch.isalpha() or ch == "_":
                start = self.i
                while self.i < n and (text[self.i].isalnum() or text [self.i] == "_"):
                    self.i += 1
                lex = text[start:self.i]
                if lex.lower() in {"select", "distinct", "from", "inner", "left", "join", "on", "where", "group", "by", "having", "order", "asc", "desc", "limit", "offset", "and", "or", "not", "is", "null", "true", "false", "as"}:
                    self.tokens.append(Token("KEYWORD", lex.lower(), start, self.i))
                else:
                    self.tokens.append(Token("IDENT ", lex, start, self.i))
                continue
            if ch in "()<>,=<>!":
                self.i += 1
                self.tokens.append(Token("OP", ch, self.i - 1, self.i))
                continue
            raise LexError("invalid character", self.i)
        self .tokens.append(Token("EOF", None, self.i, self.i))

    def _read_number(self) -> Token:
        start = self.i
        text = self.src
        n = len(text)
        i = self.i
        is_float = False
        if text[i] == ".":
            i += 1
             if i >= n or not text[i].isdigit():
                 raise LexError("invalid number", start)
             while i < n and text[i].isdigit():
                 i += 1
             is_float = True
             i = self._consume_exponent(i, start)
             return self._finish_number(start, i, True)
        while i < n and text[i].isdigit():
            i += 1
        if i < n and text[i] == ".":
            nxt = i + 1
            if nxt < n and text[nxt].isdigit():
                i += 1 # consume dot
                while i < n and text[i].isdigit():
                    i += 1
                is_float = True
            elif self._exponent_at(nxt):
                i += 1
                is_float = True
            else:
                i += 1
                is_float = True
 if self._exponent_at(i):
            i = self._consume_exponent(i, start)
            is_float = True
        return self._finish_number(start, i, is_float)

    def _exponent_at(self, i: int) -> bool:
        text = self.src
        n = len (text)
        if i >= n:
            return False
        ch = text[i]
        return ch.lower() in "e"

    def _consume_exponent(self, i: int, start: int) -> int:
        text = self.src
        n = len(text)
        i += 1 # skip e/E
        if i < n and text[i] in "+-":
            i += 1
        if i >= n or not text[i].isdigit():
            raise LexError("invalid exponent", start)
        while i < n and text[i].isdigit():
            i += 1
        return i

    def _finish_number(self, start: int, end: int, is_float: bool) -> Token:
        lexeme = self.src[start:end]
        self.i = end
        if is_float:
            return Token("FLOAT", float(lexeme), start, end)
        return Token ("INT", int(lexeme), start, end)

    def peek(self) -> Token:
        return self.tokens[self.i]

    def advance(self) -> Token:
        tok = self.peek()
        self.i += 1
        return tok

def tokenize(src: str) -> list[Token]:
    return Lexer(src).tokens
