# microdb/parser.py
from dataclasses import dataclass, replace
from typing import Any

@dataclass(frozen=True)
class Token:
    kind: str
    value: Any
    start: int
    end: int

@dataclass(frozen=True )
class Expr:
    source: str

@dataclass(frozen=True)
class Literal(Expr):
    value: Any

@dataclass(frozen=True)
class ColumnRef(Expr):
    table: str | None
    name: str

@dataclass(frozen=True)
class BinaryOp(Expr):
    op: str
    left: Expr
    right: Expr

@dataclass(frozen=True)
class UnaryOp(Expr):
    op: str
    operand: Expr

@dataclass(frozen=True)
class IsNull(Expr):
    operand: Expr
    negated: bool

@dataclass(frozen=True)
class Func Call(Expr):
    name: str
    args: tuple[Expr, ...]
    star: bool

@dataclass(frozen=True)
class SelectItem:
    kind: str # "expr" or "star" or "table_star"
    expr: Expr | None
    alias: str | None
 source: str

@dataclass(frozen=True)
class JoinClause:
    kind: str
    table: str
    on: Expr

@dataclass(frozen=True)
class Query:
    distinct: bool
    items: tuple[SelectItem, ...]
    from_table: str
    join: JoinClause | None
    where: Expr | None
    group_by: tuple[Expr, ...]
    having: Expr | None
    order_by: tuple[tuple[Expr, str], ...]
    limit: int | None
    offset: int | None

class Parser:
    def __init__(self , tokens: list[Token], sql: str):
        self.tokens = tokens
        self.sql = sql
        self.pos = 0
        self._agg_depth = 0

    def _error(self, msg: str) -> None:
        raise ParseError(msg, self.peek().start)

    def peek(self) -> Token:
        return self.tokens[self.pos]

    def advance(self) -> Token:
        tok = self.peek()
        self.pos += 1
        return tok

    def match_kw(self, kw: str) -> bool:
        if self.peek().kind == "KEYWORD" and self.peek().value == kw:
            self.advance()
            return True
        return False

    def match_op(self, op: str) -> bool:
        if self.peek().kind == "OP" and self.peek().value == op:
            self.advance()
            return True
        return False

    def expect_kw(self, kw: str) -> Token:
        tok = self.peek()
        if tok.kind == "KEYWORD" and tok.value == kw:
            return self.advance()
        raise ParseError(f"expected {kw}", tok.start)

    def expect_ident(self) -> str:
        tok = self.peek ()
        if tok.kind != "IDENT":
            raise ParseError("expected identifier", tok.start)
        return self.advance().value

    def expect_op(self, op: str) -> Token:
        tok = self.peek()
        if tok.kind == "OP" and tok.value == op:
            return self.advance ()
        raise ParseError(f"expected {op}", tok.start)

    def expect_eof(self) -> None:
        if self.peek().kind != "EOF":
            raise ParseError("unexpected token", self.peek().start)

    def _span(self, start: int) -> str:
        end = self .tokens[self.pos - 1].end
        return self._collapse_ws(self.sql[start:end])

    def _collapse_ws(self, s: str) -> str:
        return " ".join(s.split())

    def parse_query(self) -> Query:
        self.expect_kw("SELECT")
        distinct = self.match _kw("DISTINCT")
        items = self.parse_select_list()
        self.expect_kw("FROM")
        table = self.expect_ident()
        join = self.parse_join()
        where = self.parse_optional_where()
        group_by = self.parse_optional_group()
        having = self.parse_optional_having()
        order_by = self.parse_optional_order()
        limit = self.parse_optional_limit()
        offset = self.parse_optional_offset()
        self.expect_eof()
        return Query(distinct, items, table, join, where, group_by, having, order_by, limit, offset)

    def parse_select_list(self) -> tuple[ SelectItem, ...]:
        items = [self.parse_select_item()]
        while self.match_op(","):
            items.append(self.parse_select_item())
        return tuple(items)

    def parse_select_item(self) -> SelectItem:
        if self._is_star_item():
            return self._parse_star_item()
        start = self.peek().start
        expr = self.parse_or()
        alias = None
        if self.match_kw("AS"):
            alias = self.expect_ident()
        source = self._span(start)
        return SelectItem("expr", expr, alias, None, source)

    def _is_star_item(self) -> bool:
        t = self.peek()
        if t.kind == "OP" and t.value == "*":
            return True
        if t.kind == "IDENT" and self._ahead(1, "OP", ".") and self._ahead(2, "OP", "*"):
            return True
        return False

    def _ahead(self, n: int, kind: str, value: object) -> bool:
        idx = self.pos + n
        if idx >= len(self.tokens):
            return False
        tok = self.tokens[idx]
        return tok.kind == kind and tok.value == value

    def _parse_star_item(self) -> SelectItem:
        start = self.peek().start
        if self.match_op("*"):
            return SelectItem("star", None, None, None, self._span(start))
        table = self.expect_ident()
        self.expect_op(".")
        self.expect_op("*")
        return SelectItem("table_star", None, None, table, self._span(start))

    def parse_join(self) -> JoinClause | None:
        kind = None
        if self.match_kw("INNER"):
            kind = "INNER"
        elif self.match_kw("LEFT"):
            kind = "LEFT"
        else :
            return None
        self.expect_kw("JOIN")
        table = self.expect_ident()
        self.expect_kw("ON")
        on = self.parse_or()
        return JoinClause(kind, table, on)

    def parse_optional_where(self) -> Expr | None:
        if not self.match_kw("WHERE"):
 return None
        return self.parse_or()

    def parse_optional_group(self) -> tuple[Expr, ...]:
        if not self.match_kw("GROUP"):
            return ()
        self.expect_kw("BY")
        exprs = [self.parse_or()]
        while self.match_op(","):
            exprs.append(self.parse _or())
        return tuple(exprs)

    def parse_optional_having(self) -> Expr | None:
        if not self.match_kw("HAVING"):
            return None
        return self.parse_or()

    def parse_optional_order(self) -> tuple[tuple[Expr, str], ...]:
        if not self .match_kw("ORDER"):
            return ()
        self.expect_kw("BY")
        items = [self.parse_order_item()]
        while self.match_op(","):
            items.append(self.parse_order_item())
        return tuple(items)

    def parse_order_item(self) -> tuple[Expr, str]:
        expr = self.parse _or()
        direction = "ASC"
        if self.match_kw("DESC"):
            direction = "DESC"
        elif self.match_kw("ASC"):
            direction = "ASC"
        return expr, direction

    def parse_optional_limit(self) -> int | None:
        if not self.match_kw("LIMIT"):
 return None
        tok = self.peek()
        if tok.kind != "INT":
            raise ParseError("expected integer", tok.start)
        self.advance()
        return int(tok.value)

    def parse_optional_offset(self) -> int | None:
        if not self.match_kw("OFFSET"):
            return None
        tok = self.peek()
        if tok.kind != "INT":
            raise ParseError("expected integer", tok.start)
        self.advance()
        return int(tok.value)

    def parse_or(self) -> Expr:
        start = self.peek().start
        left = self.parse_and()
        while self.match_kw(" OR"):
            right = self.parse_and()
            left = BinaryOp("OR", left, right, self._span(start))
        return left

    def parse_and(self) -> Expr:
        start = self.peek().start
        left = self.parse_not()
        while self.match_kw("AND"):
            right = self.parse_not()
            left = BinaryOp("AND", left, right, self._span(start))
        return left

    def parse_not(self) -> Expr:
        if self.match_kw("NOT"):
            start = self.peek().start
            operand = self.parse_not()
            return UnaryOp("NOT ", operand, self._span(start))
        return self.parse_predicate()

    def parse_predicate(self) -> Expr:
        start = self.peek().start
        left = self.parse_additive()
        if self._at_cmp():
            op = self.advance().value
            right = self.parse_additive()
 return BinaryOp(str(op), left, right, self._span(start))
        if self.match_kw("IS"):
            negated = self.match_kw("NOT")
            self.expect_kw("NULL")
            return IsNull(left, negated, self._span(start))
        return left

    def _at_cmp(self) -> bool:
        t = self.peek()
        return t.kind == "OP" and t.value in ("=", "<>", "<", "<=", ">", ">=")

    def parse_additive(self) -> Expr:
        start = self.peek().start
        left = self.parse_mult()
        while self.match_op("+ ") or self.match_op("-"):
            op = self.advance().value
            right = self.parse_mult()
            left = BinaryOp(str(op), left, right, self._span(start))
        return left

    def parse_mult(self) -> Expr:
        start = self.peek().start
        left = self .parse_unary()
        while self.match_op("*") or self.match_op("/") or self.match_op("%"):
            op = self.advance().value
            right = self.parse_unary()
            left = BinaryOp(str(op), left, right, self._span(start))
        return left

    def parse_un ary(self) -> Expr:
        if self.match_op("-"):
            start = self.peek().start
            operand = self.parse_unary()
            return UnaryOp("-", operand, self._span(start))
        return self.parse_primary()

    def parse_primary(self) -> Expr:
        tok = self.peek()
        if tok.kind == "INT":
            self.advance()
            return Literal(tok.value, self._span(tok.start))
        if tok.kind == "FLOAT":
            self.advance()
            return Literal(tok.value, self._span(tok.start))
        if tok.kind == "TEXT":
            self.advance()
            return Literal(tok.value, self._span(tok.start))
        if tok.kind == "KEYWORD":
            if tok.value == "true":
                self.advance()
                return Literal(True, self._span(tok.start))
            if tok.value == "false":
                self.advance()
                return Literal(False, self._span(tok.start))
            if tok .value == "null":
                self.advance()
                return Literal(None, self._span(tok.start))
